template<class A,class B>bool equivalent(const A&a,const B&b){
 if constexpr(std::is_arithmetic_v<A>||std::is_same_v<A,std::string>)return a==b;
 else if constexpr(has_time<A>::value)return a.time==b.time&&a.beat==b.beat&&a.numerator==b.numerator&&a.denominator==b.denominator;
 else if constexpr(has_span<A>::value)return a.start_beat==b.start_beat&&a.end_beat==b.end_beat&&a.numerator==b.numerator&&a.denominator==b.denominator&&a.abc_numerator==b.abc_numerator&&a.abc_denominator==b.abc_denominator&&a.pad_before==b.pad_before;
 else if constexpr(has_groups<A>::value)return equivalent(a.measures,b.measures)&&a.structure_labels==b.structure_labels&&a.meter_changed==b.meter_changed&&a.key_changed==b.key_changed;
 else if constexpr(has_interval<A>::value)return a.start==b.start&&a.end==b.end&&a.value==b.value;
 else{if(a.size()!=b.size())return false;for(size_t i=0;i<a.size();++i)if(!equivalent(a[i],b[i]))return false;return true;}
}
