void full_result_late_A(){auto events=fixture(2,145);reset();auto actual_a=active_handle;auto a=ss::finish_sheetsage_output(events,72,17,3,2,{5120,2},actual_a);require(!actual_a->cancelled(),"completed actual A result clear");reset();auto actual_b=active_handle;arm=7;gate=true;engine::runtime::TaskResult b;std::thread worker([&]{b=ss::finish_sheetsage_output(events,72,17,3,2,{5120,2},actual_b);returned=true;cv.notify_all();});bool reached=false;{std::unique_lock<std::mutex>lock(mutex);reached=cv.wait_for(lock,std::chrono::seconds(2),[]{return entered.load()||returned.load();})&&entered;if(reached)actual_a->cancel();release_gate=true;cv.notify_all();}worker.join();require(reached&&actual_a!=actual_b&&actual_a->cancelled()&&!actual_b->cancelled()&&!expired,"actual completed A transitions during full B output work");same_result(a,b);++fixtures;}

